companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}

# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# Digits helper via regex
is_e164 = fun(phone) {
    return regex.test(phone, "^\\+1[0-9]{10}$")
}

normalize_phone = fun(phone) {
    # Extract digits only
    caps = regex.find_all(phone, "[0-9]")
    digits = text.join(caps, "")
    # If 11 digits starting with 1, use last 10; if 10 digits, use those
    d = if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return text.slice(digits, 1, 11)
    } else if text.length(digits) == 10 {
        return digits
    } else if text.length(digits) > 10 and text.starts_with(digits, "1") {
        return text.slice(digits, 1, 11)
    } else if text.length(digits) >= 10 {
        return text.slice(digits, text.length(digits) - 10, text.length(digits))
    } else {
        return digits
    }
    return "+1" + d
}

results = for contact in contacts {
    need_phone = contact.phone != null and contact.phone != "" and not regex.test(contact.phone, "^\\+1[0-9]{10}$")
    new_phone = normalize_phone(contact.phone) if need_phone else null

    need_company = (contact.company == null or contact.company == "") and contact.email != null and contact.email != ""
    domain = if need_company {
        parts = text.split(contact.email, "@")
        return parts[1] if list.length(parts) >= 2 else null
    } else {
        return null
    }
    new_company = domain_map[domain] if domain != null and domain in domain_map else null
    do_company = new_company != null

    updated = if need_phone and do_company {
        return update_contact({ id: contact.id, phone: new_phone, company: new_company })
    } else if need_phone {
        return update_contact({ id: contact.id, phone: new_phone })
    } else if do_company {
        return update_contact({ id: contact.id, company: new_company })
    } else {
        return null
    }

    return {
        phone_fixed: need_phone,
        company_filled: do_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submit }

